package ai

import (
	"context"
	"encoding/json"
	"errors"
	"fmt"
	"regexp"
	"strings"
)

// PlanItem represents a single recipe container deployment in the execution plan.
type PlanItem struct {
	Recipe      string            `json:"recipe"`
	Scope       string            `json:"scope,omitempty"`
	Environment map[string]string `json:"environment,omitempty"`
	Description string            `json:"description,omitempty"`
}

// ExecutionPlan is the structured response generated by the LLM planner.
type ExecutionPlan struct {
	Explanation string     `json:"explanation,omitempty"`
	Plan        []PlanItem `json:"plan"`
}

// markdownCodeBlockRegex matches ```json ... ``` or ``` ... ``` blocks.
var markdownCodeBlockRegex = regexp.MustCompile("(?s)```(?:json)?\\s*([\\s\\S]*?)\\s*```")

// ParseExecutionPlan extracts and parses an ExecutionPlan from raw LLM output text.
// It handles markdown fences, embedded JSON objects, and raw JSON arrays.
func ParseExecutionPlan(raw string) (*ExecutionPlan, error) {
	trimmed := strings.TrimSpace(raw)
	if trimmed == "" {
		return nil, errors.New("empty response from LLM")
	}

	// 1. Try stripping markdown code fences if present.
	if matches := markdownCodeBlockRegex.FindStringSubmatch(trimmed); len(matches) > 1 {
		trimmed = strings.TrimSpace(matches[1])
	}

	// 2. Try direct object unmarshal: {"explanation": "...", "plan": [...]}
	var plan ExecutionPlan
	if err := json.Unmarshal([]byte(trimmed), &plan); err == nil && len(plan.Plan) > 0 {
		normalizePlan(&plan)
		return &plan, nil
	}

	// 3. Try direct array unmarshal: [{"recipe": "..."}]
	var items []PlanItem
	if err := json.Unmarshal([]byte(trimmed), &items); err == nil && len(items) > 0 {
		plan = ExecutionPlan{
			Explanation: "Deployment plan generated from prompt",
			Plan:        items,
		}
		normalizePlan(&plan)
		return &plan, nil
	}

	// 4. Try extracting outermost JSON object {...} or array [...]
	extracted := extractJSON(trimmed)
	if extracted != "" && extracted != trimmed {
		if err := json.Unmarshal([]byte(extracted), &plan); err == nil && len(plan.Plan) > 0 {
			normalizePlan(&plan)
			return &plan, nil
		}
		if err := json.Unmarshal([]byte(extracted), &items); err == nil && len(items) > 0 {
			plan = ExecutionPlan{
				Explanation: "Deployment plan generated from prompt",
				Plan:        items,
			}
			normalizePlan(&plan)
			return &plan, nil
		}
	}

	return nil, fmt.Errorf("failed to parse structured execution plan from LLM output:\n%s", raw)
}

func normalizePlan(plan *ExecutionPlan) {
	for i := range plan.Plan {
		item := &plan.Plan[i]
		item.Recipe = strings.TrimSpace(item.Recipe)
		scope := strings.ToLower(strings.TrimSpace(item.Scope))
		if scope == "" {
			scope = "project"
		}
		item.Scope = scope
		if item.Environment == nil {
			item.Environment = make(map[string]string)
		}
	}
}

// extractJSON attempts to locate the first JSON object or array in a text string.
func extractJSON(s string) string {
	startObj := strings.Index(s, "{")
	endObj := strings.LastIndex(s, "}")
	startArr := strings.Index(s, "[")
	endArr := strings.LastIndex(s, "]")

	// If object starts first and ends after
	if startObj != -1 && endObj > startObj {
		if startArr == -1 || startObj < startArr {
			return strings.TrimSpace(s[startObj : endObj+1])
		}
	}

	// If array starts first
	if startArr != -1 && endArr > startArr {
		return strings.TrimSpace(s[startArr : endArr+1])
	}

	return ""
}

// GenerateExecutionPlan connects the catalog summarizer, prompt builder, LLM client,
// and JSON parser into an end-to-end planning workflow.
func GenerateExecutionPlan(ctx context.Context, client Client, userPrompt string) (*ExecutionPlan, error) {
	catalogSummary, err := SummarizeCatalog()
	if err != nil {
		return nil, fmt.Errorf("summarizing recipe catalog: %w", err)
	}

	systemPrompt := BuildSystemPrompt(catalogSummary)

	rawResponse, err := client.Generate(ctx, systemPrompt, userPrompt)
	if err != nil {
		return nil, fmt.Errorf("calling LLM: %w", err)
	}

	plan, err := ParseExecutionPlan(rawResponse)
	if err != nil {
		return nil, err
	}

	if len(plan.Plan) == 0 {
		return nil, errors.New("LLM produced an empty execution plan")
	}

	return plan, nil
}
